import UIKit

enum ArtStudioDirectPages {
    private static let pages: [String] = [
        "...TRUNCATED...",
        "...TRUNCATED..."
    ]

    static func image(at rawIndex: Int) -> UIImage {
        let index = min(max(rawIndex, 0), pages.count - 1)
        guard let data = Data(base64Encoded: pages[index]),
              let image = UIImage(data: data)?.withRenderingMode(.alwaysOriginal) else {
            return fallback
        }
        return image
    }

    private static var fallback: UIImage {
        let size = CGSize(width: 240, height: 176)
        let format = UIGraphicsImageRendererFormat()
        format.opaque = true
        format.scale = 1
        return UIGraphicsImageRenderer(size: size, format: format).image { renderer in
            renderer.cgContext.setFillColor(UIColor.white.cgColor)
            renderer.cgContext.fill(CGRect(origin: .zero, size: size))
        }
    }
}